import numpy as np

def margin_width(w, b):
    # distance from the line w.x + b = 0 to the edge where w.x + b = 1
    return 1 / np.linalg.norm(w)

def support_points(X, y, w, b, tol=1e-6):
    # indices i, in order, with s_i (w.x_i + b) = 1 within tol,
    # where s_i = -1 for class 0 and +1 for class 1
    s = np.where(np.asarray(y) == 1, 1, -1)
    v = s * (np.asarray(X, float) @ np.asarray(w, float) + b)
    return [int(i) for i in np.flatnonzero(np.abs(v - 1) <= tol)]

from sklearn.svm import SVC

def svm_report(X_train, y_train, X_test, y_test, C, gamma=None):
    # gamma None: kernel="linear"; otherwise kernel="rbf" with that gamma
    # return (support vectors, training accuracy, test accuracy),
    # the accuracies rounded to 4 places
    if gamma is None:
        m = SVC(kernel="linear", C=C)
    else:
        m = SVC(kernel="rbf", C=C, gamma=gamma)
    m.fit(X_train, y_train)
    return (len(m.support_), round(m.score(X_train, y_train), 4),
            round(m.score(X_test, y_test), 4))

from sklearn.svm import SVC

def pick_gamma(X, y, C, gammas=(0.01, 0.1, 1, 10), n_val=100):
    # fit SVC(kernel="rbf", C=C, gamma=g) on all but the last n_val rows
    # and score it on the last n_val rows
    # return (best gamma, its validation accuracy rounded to 4 places);
    # a tie goes to the smaller gamma
    Xf, yf, Xv, yv = X[:-n_val], y[:-n_val], X[-n_val:], y[-n_val:]
    best, best_acc = None, -1.0
    for g in sorted(gammas):
        m = SVC(kernel="rbf", C=C, gamma=g).fit(Xf, yf)
        acc = round(m.score(Xv, yv), 4)
        if acc > best_acc:
            best, best_acc = g, acc
    return (best, best_acc)
